        .then(response => {
            if (response.status === 200) {
                res.send({
                    success: true,
                    message: 'City found.',
                    data: response.data
                });
            } else {
                res.status(400).send({
                    success: false,
                    message: 'Invalid zip code.'
                })
            }
        })
        .catch(error => {
            console.error('Error:', error);
            res.status(500).send({
                success: false,
                message: 'An error occurred while fetching the city name.',
                data: {error}
            });
        });
});

app.listen(port, () => {
    console.log(`Server is running on http://localhost:${port}`);
});
```

### Step 5: Run Your Application

In your terminal, run:

```bash
node server.js
```

Your application should now be listening on `http://localhost:3000`.

### Step 6: Testing the API

You can test this API by visiting `http://localhost:3000/api/zipcode` in your browser or using a tool like Postman.

**Example URL to retrieve a city name based on zip code:**

```
http://localhost:3000/api/zipcode?zipCode=94105
```

Replace the `zipCode` parameter with your actual zip code and observe the response. If everything is set up correctly, you should see some JSON data returned.

