🤖 [Qwen Edge] Certainly! Below is an example of how you can create and manage a singly linked list in C++. A singly linked list is a data structure where each node contains a reference to the next node, making it easy to traverse or manipulate elements.

```cpp
#include <iostream>
using namespace std;

// Define the Node class
class ListNode {
public:
    int value;
    ListNode* next = nullptr;

    // Constructor for initializing a new node with a given value
    ListNode(int val) : value(val), next(nullptr) {}
};

// Define the LinkedList class that manages the singly linked list
class SinglyLinkedList {
private:
    ListNode* head = nullptr; // Pointer to the first node

public:
    void addNode(int data) {
        ListNode* newNode = new ListNode(data); // Create a new node with the given value
        if (!head) {                           // If it's the first node, point head to this new node
            head = newNode;
        } else {
            ListNode* current = head;           // Start at the beginning of the list
            while (current->next) {
                current = current->next;       // Move to the end of the list
            }
            current->next = newNode;            // Attach the new node to the end of the list
        }

        delete newNode;                        // Free memory allocated for the new node
    }

    void display() {
        if (head) {                           // Display nodes in a singly linked list
            ListNode* current = head;
            while (current != nullptr) {
                cout << current->value << " ";
                current = current->next;
            }
            cout << endl;
        } else {
            cout << "List is empty." << endl;  // List is not initialized, display a message instead
        }

        delete head;                          // Free memory allocated for the dummy node
    }

    ~SinglyLinkedList() {                  // Destructor to free any dynamically allocated nodes in the list
        while (head) {
            ListNode* temp = head;
            head = head->next;
            delete temp;
        }
    }
};

int main() {
    SinglyLinkedList ll;

    // Add some data into the list
    ll.addNode(1);
    ll.addNode(2);
    ll.addNode(3);

    // Display the linked list content
    cout << "Contents of Linked List:" << endl;
    ll.display();

    return 0;
}
```

### Explanation:
- **Node Class**: This class represents a single node in the linked list. It includes an integer `value` and a pointer to the next node.

- **SinglyLinkedList Class**:
  - The constructor initializes the head of the list as null, setting the `head`.
  - The `addNode` method creates a new node with a given value and attaches it to the end of the list. It also deletes the newly created node after adding it.

  - The `display` method iterates through each node in the list and prints their values.

- **Destructor** (`~SinglyLinkedList()`) ensures that all dynamically allocated nodes are freed, preventing memory leaks.

### Usage:
The provided code demonstrates how to create a singly linked list, add elements (nodes), display its content, and free up any resources when the list is no longer needed.

