    Node* prev;  // Pointer to the previous node

    Node(int d) : data(d), next(nullptr), prev(nullptr) {}
};

// Define a DoublyLinkedList class that manages the doubly linked list.
class DoublyLinkedList {
private:
    Node* head;  // Head of the list, initially set to nullptr
    Node* tail;  // Tail of the list, also initially set to nullptr

public:
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}

    void append(int data) {
        Node* newNode = new Node(data);  // Create a new node with the given data

        if (!head) {                      // If there's no head
            head = tail = newNode;         // Set both head and tail to this new node
        } else {
            newNode->prev = tail;          // Point the previous pointer of new node at current tail
            tail->next = newNode;           // Point the next pointer of existing tail at new node
            tail = newNode;                 // Update the tail pointer
        }
    }

    void printList() const {
        Node* current = head;
        while (current != nullptr) {
            std::cout << "Data: " << current->data << ", Next: " << current->next->data << ", Prev: "
                      << current->prev->data << std::endl;
            current = current->next;  // Move to the next node
        }
    }

    void remove(int data) {
        Node* temp = head;                  // Initialize a temporary pointer

        while (temp != nullptr && temp->data != data) {  // Search for the given data in the list
            temp = temp->next;  // Move to the next node if the current node's data is not equal to the data we're searching for
        }

        if (!temp) {
            std::cout << "Data not found." << std::endl;
            return;
        }

        if (temp == head && temp == tail) {     // If the data we want to remove is at both ends of the list
            delete head;                       // Delete all nodes in a single pass (O(n^2))
            delete tail;
        } else {
            if (temp->prev) {                  // If there's a previous node
                temp->next->prev = temp->prev;  // Update the prev pointer of the next node to point at the previous node
            }
            if (temp->next) {                   // If there's a next node
                temp->prev->next = temp->next;   // Update the next pointer of the previous node to point at the next node
            }

            delete temp;                        // Delete this node in one pass
        }

        if (head == tail && temp == head) {    // If the data we want to remove is both the head and the tail
            head = nullptr;                    // Set the head pointer to null, effectively removing it from the list
            tail = nullptr;
        } else {
            if (temp->next) {                   // If there's a next node
                temp->next->prev = nullptr;      // Reset the previous pointer of the next node to point at null
            }
            if (temp->prev) {                   // If there's a previous node
                temp->prev->next = nullptr;      // Reset the next pointer of the previous node to point at null
            }
        }
    }

    ~DoublyLinkedList() {
        while (head != nullptr) {              // Ensure all nodes are deleted by traversing and deleting in reverse order
            Node* toDelete = head;
            head = head->next;                 // Move to the next node
            delete toDelete;                    // Delete this node from memory
        }
    }
};

int main() {
    DoublyLinkedList list;

    list.append(1);
    list.append(2);
    list.append(3);

    std::cout << "List after append operations:" << std::endl;
    list.printList();

    list.remove(2); // Remove the node with data 2
    std::cout << "List after removing a node with data 2:" << std::endl;
    list.printList();

    return 0;
}
```

This code defines a `DoublyLinkedList` class that can be used to create and manipulate a doubly linked list. The `append` method adds elements at the end of the list, while the `printList` method displays all the elements in the list. The `remove` method allows you to remove an element from anywhere in the middle of the list by passing its data as an argument.

Note that this implementation uses a C++11 or later standard because it includes features like auto and nullptr promotion, which are not available in older versions of C++.

