// FilterSlice takes a slice and a function (filterCondition) as arguments.
// It returns a new slice containing only the elements for which the filterCondition returns true.
func FilterSlice(slice []interface{}, filterCondition func(interface{}) bool) []interface{} {
	var filteredSlice []interface{}

	for _, item := range slice {
		if filterCondition(item) {
			filteredSlice = append(filteredSlice, item)
		}
	}

	return filteredSlice
}

func main() {
	// Example usage:
	slice := []interface{}{10, 20, 30, 40, 50}
	isEven := func(x interface{}) bool {
		switch v := x.(type) {
		case int:
			return v%2 == 0
		default:
			return false // Assuming the function can handle types that implement a type assertion to int.
		}
	}

	filteredSlice := FilterSlice(slice, isEven)

	fmt.Println("Original Slice:", slice)
	fmt.Println("Filtered Slice:", filteredSlice)
}
```

### Explanation:

1. **FilterCondition Function**: This function should return `true` for elements you want to keep in the new slice and `false` otherwise.

2. **main Function**:
   - We define a slice of interface types.
   - The `isEven` function is used as an example filter condition, which will keep only even numbers from our input slice.

3. **FilterSlice Function**: This function iterates over the given slice and includes elements that meet the specified conditions in the new slice.

4. **Output**:
   - The original slice is printed.
   - The filtered slice (elements that meet the condition) is also printed.

