                res.status(400).send({
                    success: false,
                    message: 'Invalid zip code.'
                })
            }
        })
        .catch(error => {
            console.error('Error:', error);
            res.status(500).send({
                success: false,
                message: 'An error occurred while fetching the city name.',
                data: {error}
            });
        });
});

app.listen(port, () => {
